    8.0.0

     schema, table e types
     ora sono nullable.

  &reftitle.examples;

   Elenco delle Tabelle in un Catalogo


<?php
$conn = odbc_connect($dsn, $user, $pass);
$tables = odbc_tables($conn, 'SalesOrders', 'dbo', '%', 'TABLE');
while (($row = odbc_fetch_array($tables))) {
    print_r($row);
    break; // le righe successive sono omesse per brevità
}
?>


   &example.outputs.similar;


Array
(
    [TABLE_CAT] => SalesOrders
    [TABLE_SCHEM] => dbo
    [TABLE_NAME] => Orders
    [TABLE_TYPE] => TABLE
    [REMARKS] =>
)
